fn steps(k: Int, step: Int) -> List[Int] {
  var xs = []
  for i in range(0, k) {
    xs = append(xs, i * step)
  }
  return xs
}

fn steps(k: Int, step: Int) -> List[Int] {
  var xs = []
  var i = 0
  while i < k {
    xs = append(xs, i * step)
    i = i + 1
  }
  return xs
}

